for i in demand_points:
    for j in facilities:
        m.addConstr(x[i, j] <= y[j], name=f'link_{i}_{j}')

for i in demand_points:
    for j in facilities:
        m.addConstr(distance[i, j] * x[i, j] <= w, name=f'max_dist_{i}_{j}')

for i in demand_points:
    for j in facilities:
        if distance[i, j] > service_distance_limit:
            m.addConstr(x[i, j] == 0, name=f'distance_limit_{i}_{j}')

for i in demand_points:
    for j in facilities:
        m.addConstr(x[i, j] <= availability[i, j], name=f'availability_{i}_{j}')

for j in facilities:
    for k in facilities:
        if j < k:
            m.addConstr(dmin <= facility_distance[j, k] + big_m * (2 - y[j] - y[k]), name=f'pairwise_{j}_{k}')
